mapper.select:
SELECT * FROM scheduled_task

    deleted = 0

        AND task_name LIKE CONCAT('%', #{taskName}, '%')


        AND task_code LIKE CONCAT('%', #{taskCode}, '%')


        AND task_group = #{taskGroup}


        AND status = #{status}


        AND task_type = #{taskType}


        AND is_builtin = #{isBuiltin}


ORDER BY create_time DESC
